{
  "groups": [
    {
      "group_id": "g0112",
      "clusters": [
        {
          "label": "Thermoelectric performance (ionic)",
          "definition": "Overall performance of thermoelectric materials or cells operating through ionic transport.",
          "members": ["m04228", "m04437", "m05132", "m05411", "m05935", "m07270", "m08625"],
          "reason": "The supplied contexts identify ionic thermoelectric systems. Different formulations and improvement mechanisms qualify the claims, while the performance concept is shared."
        },
        {
          "label": "Thermoelectric performance",
          "definition": "Overall thermoelectric performance discussed through bonding, structural distortion, or thermal and electrical transport.",
          "members": ["m08499", "m09302", "m10102", "m16291"],
          "reason": "These passages use the broad performance concept without defining a particular metric or explicitly isolating an ionic or thermogalvanic subtype."
        },
        {
          "label": "Thermoelectric performance (electronic)",
          "definition": "Thermoelectric performance associated with electronic carrier transport in conducting materials.",
          "members": ["m09748", "m10990", "m11267", "m11851", "m12491", "m14088", "m14155", "m16411", "m16661"],
          "reason": "The carrier, electronic-structure, conducting-polymer, and solid-state transport contexts support a shared electronic thermoelectric performance concept. Material identities and proposed improvements remain claim-specific."
        },
        {
          "label": "Thermoelectric performance (calculated)",
          "definition": "Thermoelectric performance evaluated using first-principles electronic and transport calculations.",
          "members": ["m11241", "m11249", "m26995"],
          "reason": "All three explicitly describe calculated performance. They remain separate from performance reported without this computational qualification."
        },
        {
          "label": "Thermoelectric performance (thermoelectrochemical cells)",
          "definition": "Thermoelectric performance of electrolyte-based thermoelectrochemical cells.",
          "members": ["m08682"],
          "reason": "The title explicitly identifies thermoelectrochemical cells, and the relations concern statistical determinants of their performance."
        },
        {
          "label": "Thermoelectric performance (P/λ evaluation)",
          "definition": "Performance of a mixed ion-electron conducting thermoelectric cell evaluated by optimal output power density divided by active-material thermal conductivity.",
          "members": ["m08912"],
          "reason": "The evidence specifies both a mixed-conduction system and a particular performance evaluation ratio."
        }
      ],
      "unresolved": []
    },
    {
      "group_id": "g0113",
      "clusters": [
        {
          "label": "Capacitance",
          "definition": "Electrical charge-storage capacity per unit potential difference.",
          "members": ["m04230", "m18216"],
          "reason": "Both refer to electrical capacitance. Material composition, frequency dependence, and polarization explanations qualify the measurements rather than change the quantity."
        }
      ],
      "unresolved": []
    },
    {
      "group_id": "g0114",
      "clusters": [
        {
          "label": "Thermoelectric power (mixed ionic-electronic)",
          "definition": "Net thermopower in conductors whose response involves ionic and electronic transport.",
          "members": ["m08180", "m08946", "m08976"],
          "reason": "The evidence connects thermopower with mixed conduction, electronic contributions, or ionic transference numbers. These are net responses, not separately identified ionic or electronic coefficients."
        },
        {
          "label": "Thermoelectric power (electronic)",
          "definition": "Thermopower characterizing the electrical response to a temperature difference in electronic transport.",
          "members": ["m09144", "m12795", "m17417", "m19578", "m23144"],
          "reason": "Electronic states, semiconductor carrier type, reduced transition-metal fractions, or electronic defect compensation establish electronic thermopower. Carrier signs and sample compositions remain attached to their claims."
        },
        {
          "label": "Thermoelectric power (c-axis)",
          "definition": "Thermopower measured along the c-axis of sodium hydride graphite intercalation compounds.",
          "members": ["m11777"],
          "reason": "The title specifies the measurement direction; the evidence additionally identifies a predominantly phonon-drag interpretation."
        },
        {
          "label": "Thermoelectric power",
          "definition": "Thermopower, the thermally induced electrical response conventionally represented by the Seebeck coefficient.",
          "members": ["m11784", "m12983", "m19692", "m26262"],
          "reason": "The contexts identify thermopower as a transport property, including explicit notation S or TEP, but do not establish a shared narrower carrier or directional subtype."
        }
      ],
      "unresolved": [
        {
          "member": "m04234",
          "reason": "The porosity statement does not establish whether 'power' means thermopower, generated voltage, or electrical output power."
        },
        {
          "member": "m06537",
          "reason": "The statement that no thermoelectric power was observed supplies no definition or units distinguishing thermopower from output power or voltage."
        },
        {
          "member": "m16066",
          "reason": "The evidence identifies a Seebeck-related source of an interface field but does not resolve whether the label denotes a coefficient, thermoelectric voltage, or field-generating effect."
        },
        {
          "member": "m22110",
          "reason": "The interface-field context does not distinguish thermopower as a material coefficient from a growth-dependent thermoelectric voltage or contribution."
        },
        {
          "member": "m24031",
          "reason": "Association with a temperature-gradient-generated field establishes a thermoelectric origin but does not define the labeled quantity sufficiently for equivalence."
        }
      ]
    },
    {
      "group_id": "g0115",
      "clusters": [
        {
          "label": "Low-grade waste energy harvesting",
          "definition": "Recovering useful electrical energy from low-grade waste heat through thermoelectric materials.",
          "members": ["m04265", "m04327"],
          "reason": "Both denote the same application. Hydrogel functionalization, carrier type, and electrolyte concentration describe the candidate materials."
        }
      ],
