        {
          "label": "Wearable energy supply",
          "definition": "Use of wearable thermoelectric systems to supply electrical energy.",
          "members": ["m04294", "m04344", "m07390"],
          "reason": "All three describe the same proposed application, supported by different wearable device demonstrations."
        }
      ],
