        {
          "label": "Enhanced ionic conductivity",
          "definition": "An increase in electrical conductivity attributable to ionic transport.",
          "members": ["m04301", "m06255", "m06685"],
          "reason": "All denote the same directional improvement, rather than absolute conductivity. Design objectives, reported outcomes, and their different mechanisms remain claim-specific."
        }
      ],
