      "clusters": [
        {
          "label": "High thermovoltage",
          "definition": "A qualitatively high thermally generated voltage in an ionic thermoelectric material or device.",
          "members": ["m04304", "m04353", "m05003"],
          "reason": "All denote high thermovoltage in ionic thermoelectric contexts. Intended and reported outputs share the concept without implying a common numerical threshold."
        }
      ],
      "unresolved": []
    }
  ]
